CREATE SCHEMA IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_europe;
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_europe.epex_day_ahead_prices (price_id BIGINT, delivery_datetime TIMESTAMP, bidding_zone STRING, price_eur_mwh DECIMAL(12,4), volume_mwh DECIMAL(14,4), market_time_unit_minutes INT, auction_date DATE, data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_europe.entso_generation_mix (mix_id BIGINT, interval_datetime TIMESTAMP, bidding_zone STRING, fuel_type STRING, generation_mw DECIMAL(12,2), data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_europe.cross_border_flows (flow_id BIGINT, interval_datetime TIMESTAMP, from_zone STRING, to_zone STRING, flow_mw DECIMAL(12,2), atc_mw DECIMAL(12,2), ntc_mw DECIMAL(12,2), data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_europe.generation_portfolio (asset_id STRING, asset_name STRING, operator STRING, country STRING, fuel_type STRING, capacity_mw DECIMAL(10,2), commission_year INT, openlink_incumbent BOOLEAN);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_europe.ets_carbon_prices (price_date DATE, eua_price_eur DECIMAL(10,4), volume DECIMAL(16,2), exchange STRING, data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_europe.spark_spreads (spread_id BIGINT, calculation_datetime TIMESTAMP, bidding_zone STRING, power_price DECIMAL(12,4), gas_price_mmbtu DECIMAL(12,4), heat_rate DECIMAL(8,4), ets_price DECIMAL(10,4), spark_spread DECIMAL(12,4), clean_spark_spread DECIMAL(12,4), data_source STRING);
